class Box[+A](val value: A):
  def map[B](f: A => B): Box[B] = Box(f(value))

def maxOf[A: Ordering](xs: List[A]): A = xs.max

@main def generics(): Unit =
  val b = Box(41).map(_ + 1)
  println(b.value)
  println(maxOf(List(3, 1, 2)))
  println(maxOf(List("b", "a")))
  def pair[A, B](a: A, b: B): (A, B) = (a, b)
  println(pair(1, "one"))

