import scala.concurrent.{Future, Await}
import scala.concurrent.duration.*
import scala.concurrent.ExecutionContext.Implicits.global

@main def futures(): Unit =
  val f1 = Future { Thread.sleep(100); 20 }
  val f2 = Future { 22 }
  val sum = for
    a <- f1
    b <- f2
  yield a + b
  println(Await.result(sum, 1.second))
  val failed = Future { throw new RuntimeException("boom") }
  failed.recover { case e => s"recovered: ${e.getMessage}" }
    .foreach(println)
  Await.result(failed.recover { case _ => 0 }, 1.second)

import scala.annotation.tailrec

@main def perf(): Unit =
  val n = 1_000_000
  @tailrec
  def loop(i: Int, acc: Long): Long =
    if i > n then acc else loop(i + 1, acc + i)
  println(loop(1, 0L))

  val list = (1 to 100000).toList
  val vec  = (1 to 100000).toVector
  println(list.take(3))
  println(vec(50000))

  val lazyVals = (1 to 5).view.map(x => x * x).filter(_ % 2 == 1).toList
  println(lazyVals)

