trait Logger:
  def log(msg: String): Unit

class ConsoleLogger extends Logger:
  def log(msg: String): Unit = println(s"[console] $msg")

class Service(logger: Logger):
  def run(): Unit = logger.log("running")

object Service:
  def apply(logger: Logger = new ConsoleLogger): Service = new Service(logger)

trait TaxStrategy:
  def tax(amount: Double): Double

object FlatTax extends TaxStrategy:
  def tax(amount: Double): Double = amount * 0.1

@main def patterns(): Unit =
  Service().run()
  println(List(100.0, 200.0).map(FlatTax.tax))

case class Order(id: Long, items: List[String], total: BigDecimal)

object OrderService:
  def addItem(order: Order, item: String, price: BigDecimal): Order =
    order.copy(items = order.items :+ item, total = order.total + price)

  def find(orders: List[Order], id: Long): Option[Order] =
    orders.find(_.id == id)

@main def style(): Unit =
  val o = Order(1, Nil, BigDecimal(0))
  val o2 = OrderService.addItem(o, "book", BigDecimal(42))
  println(OrderService.find(List(o2), 1).map(_.total))
